import React, { useState, useEffect } from 'react';
import { Sprinter } from '@chainsafe/sprinter-sdk';

const SprinterWidget = () => {
  const [account, setAccount] = useState('');
  const [balances, setBalances] = useState({});
  const [totalUSDC, setTotalUSDC] = useState('0');
  const [totalUSDT, setTotalUSDT] = useState('0');
  const [selectedAmount, setSelectedAmount] = useState('');
  const [selectedDestination, setSelectedDestination] = useState('');
  const [selectedToken, setSelectedToken] = useState('USDT');
  const [quote, setQuote] = useState(null);
  const [destinationAddress, setDestinationAddress] = useState('');

  const sprinter = new Sprinter();

  const supportedChains = [
    { id: 1, name: 'Ethereum Mainnet' },
    { id: 137, name: 'Polygon' },
    { id: 42161, name: 'Arbitrum' },
    { id: 10, name: 'Optimism' },
    { id: 8453, name: 'Base' },
    { id: 100, name: 'Gnosis' },
    { id: 43114, name: 'Avalanche' },
  ];

  useEffect(() => {
    setAccount('0x1234...5678');
    fetchBalances();
  }, []);

  const fetchBalances = async () => {
    try {
      const usdcBalances = await sprinter.getUserBalances(account, ['USDC']);
      const usdtBalances = await sprinter.getUserBalances(account, ['USDT']);
      setBalances({ USDC: usdcBalances.USDC, USDT: usdtBalances.USDT });

      setTotalUSDC(calculateTotal(usdcBalances.USDC));
      setTotalUSDT(calculateTotal(usdtBalances.USDT));
    } catch (error) {
      console.error('Error fetching balances:', error);
    }
  };

  const calculateTotal = (balances) => {
    return balances.reduce((acc, bal) => acc + BigInt(bal.balance), BigInt(0)).toString();
  };

  const handlePayClick = async () => {
    try {
      const solution = await sprinter.getSolution({
        account,
        token: selectedToken,
        destinationChain: parseInt(selectedDestination),
        amount: selectedAmount
      });
      setQuote(solution[0]);
    } catch (error) {
      console.error('Error getting quote:', error);
    }
  };

  const handleAggregateClick = async () => {
    try {
      console.log('Executing transaction with quote:', quote);
      setQuote(null);
      setSelectedAmount('');
      setSelectedDestination('');
      setDestinationAddress('');
    } catch (error) {
      console.error('Error executing transaction:', error);
    }
  };

  const renderBalanceScreen = () => (
    <div style={{ border: '1px solid black', padding: '20px', marginBottom: '20px' }}>
      <h2>Balance Screen</h2>
      <p>Wallet: {account}</p>
      {supportedChains.map((chain) => (
        <div key={chain.id}>
          <h3>{chain.name}</h3>
          <p>USDC: {balances.USDC?.find(b => b.chainId === chain.id)?.balance || '0'}</p>
          <p>USDT: {balances.USDT?.find(b => b.chainId === chain.id)?.balance || '0'}</p>
        </div>
      ))}
      <h3>Total Balances</h3>
      <p>USDC: {totalUSDC}</p>
      <p>USDT: {totalUSDT}</p>
      <input
        type="number"
        value={selectedAmount}
        onChange={(e) => setSelectedAmount(e.target.value)}
        placeholder="Amount"
      />
      <select
        value={selectedDestination}
        onChange={(e) => setSelectedDestination(e.target.value)}
      >
        <option value="">Select destination chain</option>
        {supportedChains.map((chain) => (
          <option key={chain.id} value={chain.id}>{chain.name}</option>
        ))}
      </select>
      <select
        value={selectedToken}
        onChange={(e) => setSelectedToken(e.target.value)}
      >
        <option value="USDT">USDT</option>
        <option value="USDC">USDC</option>
      </select>
      <button onClick={handlePayClick}>Pay</button>
    </div>
  );

  const renderQuoteScreen = () => (
    <div style={{ border: '1px solid black', padding: '20px' }}>
      <h2>Sprinter Quote Aggregation</h2>
      <p>Total: {quote.amount} {selectedToken}</p>
      <p>Destination: {supportedChains.find(c => c.id === quote.destinationChain)?.name}</p>
      <p>Fee: {quote.fee.amount}</p>
      <p>Gas Cost: {quote.gasCost.amount}</p>
      <input
        type="text"
        value={destinationAddress}
        onChange={(e) => setDestinationAddress(e.target.value)}
        placeholder="Destination Address"
      />
      <button onClick={handleAggregateClick}>Pay/Aggregate</button>
    </div>
  );

  return (
    <div>
      {!quote && renderBalanceScreen()}
      {quote && renderQuoteScreen()}
    </div>
  );
};

export default SprinterWidget;
